cd /home/runner/work/dmtools-agents/dmtools-agents && node -e "
var raw = JSON.parse(require('fs').readFileSync('input/pr-1240/pr_discussions_raw.json','utf8'));
var out = JSON.parse(require('fs').readFileSync('outputs/review_replies.json','utf8'));
var rawMap = {}; raw.threads.forEach(function(t){ rawMap[t.threadId] = t; });
var errs = 0;
if (out.replies.length !== raw.threads.length) { console.log('COUNT MISMATCH'); errs++; }
var seen = {};
out.replies.forEach(function(r){
  var t = rawMap[r.threadId];
  if (!t) { console.log('BAD threadId', r.threadId); errs++; }
  if (r.inReplyToId !== t.rootCommentId) { console.log('BAD inReplyToId', r.threadId); errs++; }
  if (!require('fs').existsSync(r.reply)) { console.log('MISSING', r.reply); errs++; }
  if (seen[r.threadId]) { console.log('DUP', r.threadId); errs++; }
  seen[r.threadId] = 1;
});
raw.threads.forEach(function(t){ if (!seen[t.threadId]) { console.log('UNCOVERED', t.threadId); errs++; } });
console.log(errs === 0 ? 'REPLIES OK: 11/11, threadIds verbatim, inReplyToId=rootCommentId, files exist' : 'ERRORS: '+errs);
